function parseProcessArgs(argv: string[]): Record<string, string | boolean> {
  // Parse flags into an object

  const res: Record<string, string | boolean> = {};
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg.startsWith('--')) {
      const key = arg.slice(2);
      if (i + 1 < argv.length && !argv[i + 1].startsWith('--')) {
        res[key] = argv[++i];
      } else {
        res[key] = true;
      }
    }
  }
  return res;
}

