  // Run tasks and partition results

  const succeeded: T[] = [];
  const failed: string[] = [];
  for (const task of tasks) {
    try {
      const val = await task();
      succeeded.push(val);
    } catch (err: any) {
      failed.push(err && err.message ? err.message : String(err));
    }
  }
  return { succeeded, failed };
