    if (!hopByHop.has(lk)) {
      outbound[lk] = v;
    }
  }
  const prevXff = inbound['x-forwarded-for'] || inbound['X-Forwarded-For'];
  outbound['x-forwarded-for'] = prevXff ? prevXff + ', ' + clientIp : clientIp;
  outbound['x-forwarded-proto'] = 'https';
  outbound['x-request-id'] = requestId;
  return outbound;
}

